#!/usr/bin/env sh

# Builds the formula from the current workspace and runs `brew install` and
# `brew test` against a throwaway local tap. The formula published to
# 1985epma/homebrew-k8scli is generated by GoReleaser on each release.

set -eu

ROOT_DIR=$(CDPATH='' cd -- "$(dirname "$0")/.." && pwd)
TMP_DIR=$(mktemp -d)
DEFAULT_TAP_SUFFIX=$(basename "$TMP_DIR" | tr '[:upper:]' '[:lower:]' | tr -c '[:alnum:]' '-')
TAP_NAME=${TAP_NAME:-local/k8scli-test-$DEFAULT_TAP_SUFFIX}

cleanup() {
	HOMEBREW_NO_AUTO_UPDATE=1 brew uninstall --force k8scli >/dev/null 2>&1 || true
	HOMEBREW_NO_AUTO_UPDATE=1 brew uninstall --force "$TAP_NAME/k8scli" >/dev/null 2>&1 || true
	rm -rf "$TMP_DIR"
	brew untap "$TAP_NAME" >/dev/null 2>&1 || true
}

trap cleanup EXIT INT TERM

ARCHIVE="$TMP_DIR/k8scli-local.tar.gz"
FORMULA_FILE="$TMP_DIR/k8scli.rb"

HOMEBREW_NO_AUTO_UPDATE=1 brew uninstall --force k8scli >/dev/null 2>&1 || true
HOMEBREW_NO_AUTO_UPDATE=1 brew uninstall --force "$TAP_NAME/k8scli" >/dev/null 2>&1 || true
brew untap "$TAP_NAME" >/dev/null 2>&1 || true

tar -czf "$ARCHIVE" -C "$ROOT_DIR" go.mod go.sum LICENSE README.md main.go cmd internal
SHA256=$(shasum -a 256 "$ARCHIVE" | awk '{print $1}')

cat > "$FORMULA_FILE" <<FORMULA
class K8scli < Formula
  desc "Kubernetes CLI helper tool"
  homepage "https://github.com/1985epma/k8scli"
  url "file://$ARCHIVE"
  sha256 "$SHA256"
  version "0.0.0-local"
  license "MIT"

  depends_on "go" => :build

  def install
    system "go", "build", *std_go_args(ldflags: "-s -w"), "."
    bin.install_symlink "k8scli" => "k8scli-ui"
    generate_completions_from_executable(bin/"k8scli", "completion")
  end

  test do
    assert_match "k8scli version", shell_output("#{bin}/k8scli version")
    assert_predicate bin/"k8scli-ui", :symlink?
    assert_match "web console", shell_output("#{bin}/k8scli-ui --help")
  end
end
FORMULA

HOMEBREW_NO_AUTO_UPDATE=1 brew tap-new "$TAP_NAME" >/dev/null
TAP_REPO=$(brew --repo "$TAP_NAME")

mkdir -p "$TAP_REPO/Formula"
cp "$FORMULA_FILE" "$TAP_REPO/Formula/k8scli.rb"

HOMEBREW_NO_AUTO_UPDATE=1 brew install --build-from-source "$TAP_NAME/k8scli"
HOMEBREW_NO_AUTO_UPDATE=1 brew test "$TAP_NAME/k8scli"

printf 'Homebrew tap test completed for %s\n' "$TAP_NAME"
